text:
  "dDurationMs": 1485,
  "segs": [ {
    "utf8": "我其實那時候有仔細想過"
  } ]
}, {
  "tStartMs": 407290,
  "dDurationMs": 450,
  "segs": [ {
    "utf8": "因為我那時候"
  } ]
}, {
  "tStartMs": 407740,
  "dDurationMs": 1852,
  "segs": [ {
    "utf8": "自己在講這件事情的時候"
  } ]
}, {
  "tStartMs": 409592,
  "dDurationMs": 617,
  "segs": [ {
    "utf8": "我就在想說"
  } ]
}, {
  "tStartMs": 410209,
  "dDurationMs": 1335,
  "segs": [ {
    "utf8": "那我們如果是台北 "
  } ]
}, {
  "tStartMs": 411544,
  "dDurationMs": 1552,
  "segs": [ {
    "utf8": "我們要放哪一首歌"
  } ]
}, {
  "tStartMs": 413096,
  "dDurationMs": 1301,
  "segs": [ {
    "utf8": "因為我覺得那首歌 "
  } ]
}, {
  "tStartMs": 414397,
  "dDurationMs": 2135,
  "segs": [ {
    "utf8": "可能要跨度跨得夠長"
  } ]
}, {
  "tStartMs": 416532,
  "dDurationMs": 1669,
  "segs": [ {
    "utf8": "然後它的歷史也夠久"
  } ]
}, {
  "tStartMs": 418201,
  "dDurationMs": 1768,
  "segs": [ {
    "utf8": "然後它也有這樣的意象 "
  } ]
}, {
  "tStartMs": 419969,
  "dDurationMs": 934,
  "segs": [ {
    "utf8": "我這個年代"
  } ]
}, {
  "tStartMs": 420903,
  "dDurationMs": 1101,
  "segs": [ {
    "utf8": "假如我這個年代的話"
  } ]
}, {
  "tStartMs": 422004,
  "dDurationMs": 1702,
  "segs": [ {
    "utf8": "我們很多人就像剛剛有聊到"
  } ]
}, {
  "tStartMs": 423706,
  "dDurationMs": 1001,
  "segs": [ {
    "utf8": "就是 《向前走》"
  } ]
}, {
  "tStartMs": 424707,
  "dDurationMs": 1602,
  "segs": [ {
    "utf8": "這是我們這個年代聽到的歌"
  } ]
}, {
  "tStartMs": 426309,
  "dDurationMs": 984,
  "segs": [ {
    "utf8": "但我後來覺得"
  } ]
}, {
  "tStartMs": 427293,
  "dDurationMs": 1018,
  "segs": [ {
    "utf8": "如果再往前一點 "
  } ]
}, {
  "tStartMs": 428311,
  "dDurationMs": 934,
  "segs": [ {
    "utf8": "我搞不好會選"
  } ]
}, {
  "tStartMs": 429245,
  "dDurationMs": 1969,
  "segs": [ {
    "utf8": "《媽媽請你也保重》"
  } ]
}, {
  "tStartMs": 431214,
  "dDurationMs": 1785,
  "segs": [ {
    "utf8": "因為我覺得這首歌有好幾個意義"
  } ]
}, {
  "tStartMs": 432999,
  "dDurationMs": 600,
  "segs": [ {
    "utf8": "因為第一個 "
  } ]
}, {
  "tStartMs": 433599,
  "dDurationMs": 1452,
  "segs": [ {
    "utf8": "它本身是日本歌"
  } ]
}, {
  "tStartMs": 435051,
  "dDurationMs": 2052,
  "segs": [ {
    "utf8": "然後被文夏唱"
  } ]
}, {
  "tStartMs": 437103,
  "dDurationMs": 634,
  "segs": [ {
    "utf8": "然後唱的時候 "
  } ]
}, {
  "tStartMs": 437737,
  "dDurationMs": 2069,
  "segs": [ {
    "utf8": "它的內容也是要上來"
  } ]
}, {
  "tStartMs": 439806,
  "dDurationMs": 1601,
  "segs": [ {
    "utf8": "進去大都市打拚的人"
  } ]
}, {
  "tStartMs": 441407,
  "dDurationMs": 501,
  "segs": [ {
    "utf8": "沒錯"
  } ]
}, {
  "tStartMs": 441908,
  "dDurationMs": 2786,
  "segs": [ {
    "utf8": "然後它又有一段時間變成禁歌"
  } ]
}, {
  "tStartMs": 444694,
  "dDurationMs": 984,
  "segs": [ {
    "utf8": "因為有一陣子說"
  } ]
}, {
  "tStartMs": 445678,
  "dDurationMs": 1418,
  "segs": [ {
    "utf8": " 阿兵哥不能想媽媽"
  } ]
}, {
  "tStartMs": 447096,
  "dDurationMs": 2503,
  "segs": [ {
    "utf8": "所以那時候是文夏被禁的一首歌"
  } ]
}, {
  "tStartMs": 449599,
  "dDurationMs": 1501,
  "segs": [ {
    "utf8": "所以它又經歷 簡單來講"
  } ]
}, {
  "tStartMs": 451100,
  "dDurationMs": 1602,
  "segs": [ {
    "utf8": "就是我們威權的年代"
  } ]
}, {
  "tStartMs": 452702,
  "dDurationMs": 1101,
  "segs": [ {
    "utf8": "然後又到現在"
  } ]
}, {
  "tStartMs": 453803,
  "dDurationMs": 1802,
  "segs": [ {
    "utf8": "然後像我爸在外面唱歌"
  } ]
}, {
  "tStartMs": 455605,
  "dDurationMs": 1501,
  "segs": [ {
    "utf8": "也很喜歡唱這一首"
  } ]
}, {
  "tStartMs": 457106,
  "dDurationMs": 1702,
  "segs": [ {
    "utf8": "我覺得它的代表性就足夠"
  } ]
}, {
  "tStartMs": 458808,
  "dDurationMs": 584,
  "segs": [ {
    "utf8": "確實"
  } ]
}, {
  "tStartMs": 459392,
  "dDurationMs": 2102,
  "segs": [ {
    "utf8": "但是真的有很多個選項"
  } ]
}, {
  "tStartMs": 461494,
  "dDurationMs": 851,
  "segs": [ {
    "utf8": "當然要是我選 "
  } ]
}, {
  "tStartMs": 462345,
  "dDurationMs": 1017,
  "segs": [ {
    "utf8": "我可能會選這一首"
  } ]
}, {
  "tStartMs": 463362,
  "dDurationMs": 1552,
  "segs": [ {
    "utf8": "我剛剛忘了提醒你叫我 "
  } ]
}, {
  "tStartMs": 464914,
  "dDurationMs": 1385,
  "segs": [ {
    "utf8": "可以叫工頭"
  } ]
}, {
  "tStartMs": 466299,
  "dDurationMs": 2052,
  "segs": [ {
    "utf8": "直接叫工頭就好"
  } ]
}, {
  "tStartMs": 468351,
  "dDurationMs": 1768,
  "segs": [ {
    "utf8": "其實你剛剛提到 《向前走》"
  } ]
}, {
  "tStartMs": 470119,
  "dDurationMs": 1802,
  "segs": [ {
    "utf8": "林強以前是我老朋友"
  } ]
}, {
  "tStartMs": 471921,
  "dDurationMs": 2502,
  "segs": [ {
    "utf8": "所以他第一次在公眾面前"
  } ]
}, {
  "tStartMs": 474423,
  "dDurationMs": 1702,
  "segs": [ {
    "utf8": "唱出這首 《向前走》 的時候"
  } ]
}, {
  "tStartMs": 476125,
  "dDurationMs": 1201,
  "segs": [ {
    "utf8": "我人就在現場"
  } ]
}, {
  "tStartMs": 477326,
  "dDurationMs": 601,
  "segs": [ {
    "utf8": "喔 真的喔"
  } ]
}, {
  "tStartMs": 477927,
  "dDurationMs": 1184,
  "segs": [ {
    "utf8": "我超愛那首歌"
  } ]
}, {
  "tStartMs": 479111,
  "dDurationMs": 1102,
  "segs": [ {
    "utf8": "對 那個是在"
  } ]
}, {
  "tStartMs": 480213,
  "dDurationMs": 1901,
  "segs": [ {
    "utf8": "我記得以前是國立藝專"
  } ]
}, {
  "tStartMs": 482114,
  "dDurationMs": 2019,
  "segs": [ {
    "utf8": "現在好像是台北藝術大學"
  } ]
}, {
  "tStartMs": 484133,
  "dDurationMs": 2236,
  "segs": [ {
    "utf8": "那以前我跟他認識的時候 "
  } ]
}, {
  "tStartMs": 486369,
  "dDurationMs": 600,
  "segs": [ {
    "utf8": "我都覺得說"
  } ]
}, {
  "tStartMs": 486969,
  "dDurationMs": 2052,
  "segs": [ {
    "utf8": "蛤 林強要唱歌"
  } ]
}, {
